<?php
declare(strict_types=1);
require __DIR__.'/spool-lib.php';
$id=pb_text($_GET['spool']??'',24); $exp=(int)($_GET['exp']??0); $nonce=pb_text($_GET['nonce']??'',32); $sig=pb_text($_GET['sig']??'',128);
$valid=$id!=='' && pb_verify_claim($id,$exp,$nonce,$sig);
if (!$valid) {
    if (($_SERVER['REQUEST_METHOD']??'GET')==='POST') pb_json_response(['ok'=>false,'error'=>'claim_invalid_or_expired'],403);
    http_response_code(403); header('Content-Type: text/html; charset=utf-8'); echo '<!doctype html><meta name="viewport" content="width=device-width"><title>PRINTBENCH NFC</title><body style="font-family:system-ui;background:#080b0d;color:#eee;padding:28px"><h1>Claim abgelaufen</h1><p>Bitte in PRINTBENCH einen neuen NFC-QR-Code erzeugen.</p></body>'; exit;
}
$data=pb_load_spools(); $i=pb_find_index($data,$id);
if ($i<0) { if (($_SERVER['REQUEST_METHOD']??'GET')==='POST') pb_json_response(['ok'=>false,'error'=>'not_found'],404); http_response_code(404); exit('Spule nicht gefunden'); }
$s=$data['spools'][$i];
if (($_SERVER['REQUEST_METHOD']??'GET')==='POST') {
    try { $body=pb_body(); $bound=pb_bind_nfc_uid($id,$body['uid']??'',pb_text($body['tagType']??'NTAG216',32)); pb_json_response(['ok'=>true,'spool'=>pb_public_spool($bound),'nfc_uid'=>$bound['nfc_uid']]); }
    catch(InvalidArgumentException $e){ pb_json_response(['ok'=>false,'error'=>'uid'],422); }
    catch(OutOfBoundsException $e){ pb_json_response(['ok'=>false,'error'=>'not_found'],404); }
    catch(RuntimeException $e){ $msg=$e->getMessage(); if(str_starts_with($msg,'uid_already_bound:'))pb_json_response(['ok'=>false,'error'=>'uid_already_bound','bound_to'=>substr($msg,18)],409); if($msg==='spool_already_has_different_uid')pb_json_response(['ok'=>false,'error'=>$msg],409); throw $e; }
}
$nfcUrl='https://www.dezender.de/3d-druck/index.php?spool='.rawurlencode($id).'#spools';
header('Content-Type: text/html; charset=utf-8'); header('Cache-Control: no-store');
