y" id="copyUrl">URL KOPIEREN</button><form class="input" id="uidForm"><input id="uid" autocomplete="off" autocapitalize="characters" placeholder="z. B. 04:85:C8:5A:40:2B:80" required><button type="submit">UID MIT <?=htmlspecialchars($id)?> VERKNÜPFEN</button></form><p id="result" class="muted">Claim gültig bis <?=htmlspecialchars(gmdate('H:i:s',$exp))?> UTC.</p></section></main><script>
const claim=location.href;document.getElementById('copyUrl').onclick=async()=>{await navigator.clipboard.writeText(document.getElementById('nfcUrl').textContent);document.getElementById('result').textContent='URL kopiert.'};document.getElementById('uidForm').onsubmit=async e=>{e.preventDefault();const out=document.getElementById('result');out.className='muted';out.textContent='Verknüpfe …';try{const r=await fetch(claim,{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({uid:document.getElementById('uid').value,tagType:'NTAG216'})});const j=await r.json();if(!r.ok)throw new Error(j.error||('HTTP '+r.status));out.className='ok';out.textContent='Fertig: '+j.nfc_uid+' ist mit <?=htmlspecialchars($id)?> verknüpft.'}catch(err){out.className='bad';out.textContent='Fehler: '+err.message}};
